import re
from fractions import Fraction


_COMPONENT = re.compile(r"([0-9]+(?:\.[0-9]+)?)(ms|[wdhms])")
_UNIT_MILLISECONDS = {
    "w": 7 * 24 * 60 * 60 * 1000,
    "d": 24 * 60 * 60 * 1000,
    "h": 60 * 60 * 1000,
    "m": 60 * 1000,
    "s": 1000,
    "ms": 1,
}
_UNIT_ORDER = {unit: index for index, unit in enumerate(("w", "d", "h", "m", "s", "ms"))}


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("duration must be a string")

    value = text.strip()
    negative = value.startswith("-")
    if negative:
        value = value[1:]
    if not value or value.startswith("+"):
        raise ValueError("invalid duration")

    components = []
    position = 0
    while position < len(value):
        match = _COMPONENT.match(value, position)
        if match is None:
            raise ValueError("invalid duration")
        number_text, unit = match.groups()
        components.append((number_text, unit))
        position = match.end()
        if position < len(value):
            if value[position] == " ":
                position += 1
                if position == len(value) or value[position] == " ":
                    raise ValueError("invalid duration")

    total = Fraction(0)
    previous_order = -1
    for index, (number_text, unit) in enumerate(components):
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("invalid duration")
        previous_order = order
        if "." in number_text and index != len(components) - 1:
            raise ValueError("invalid duration")

        whole, dot, fraction_digits = number_text.partition(".")
        numerator = int(whole)
        denominator = 1
        if dot:
            denominator = 10 ** len(fraction_digits)
            numerator = numerator * denominator + int(fraction_digits)
        total += Fraction(numerator * _UNIT_MILLISECONDS[unit], denominator)

    whole, remainder = divmod(total.numerator, total.denominator)
    if remainder * 2 >= total.denominator:
        whole += 1
    return -whole if negative else whole
